# -*- coding: utf-8 -*-
import re
h = open('board_v1.html', encoding='utf-8').read()
N = '&nbsp;'

# ---- 1. prune superseded 5-oct daily counters ----
lis = re.findall(r'      <li><b>Nuevo hoy \(5-oct\).*?</li>\n', h, re.S)
print('bullets 5-oct found:', len(lis))
PRUNE_KEYS = [
 'el contraste del día: 23 departamentos en alerta roja por sensación térmica',
 'los diez descartes de la investigación de prensa',
 'la alerta roja de incendio llega a CERO municipios',
 'la lluvia se apaga en todo el país de un día para otro',
 'por primera vez en esta serie las tres capas de alerta ceden el mismo día',
 'el hallazgo del día, y es incómodo: la lluvia se fue de Urabá',
 'el desfase de dos días queda probado por séptima vez',
 'cero récords de los dos tipos el mismo día',
]
removed = 0
for li in lis:
    if any(k in li for k in PRUNE_KEYS):
        h = h.replace(li, ''); removed += 1
    else:
        h = h.replace(li, li.replace('<b>Nuevo hoy (5-oct) —', '<b>Se mantiene del 5-oct —', 1))
print('pruned:', removed)

# ---- 2. new 6-oct bullets, inserted right after <ul> ----
B = []
B.append('<b>Nuevo hoy (6-oct) — tres récords de temperatura de octubre en un solo día, y los tres son de ciudades donde nadie los busca: Medellín, Quibdó y Palmira.</b> El <b>Informe Técnico Diario N.º 278</b> registra que el <b>4 de octubre</b> tres estaciones superaron su máximo histórico del mes: <b>La Aldea (Medellín, Antioquia) con 29,0'+N+'°C</b>, sobre los 28,6 del 01/10/2023; <b>Aeropuerto El Caraño (Quibdó, Chocó) con 34,5'+N+'°C</b>, sobre los 34,2 del 05/10/2005; y <b>Aeropuerto Alfonso Bonilla (Palmira, Valle del Cauca) con 33,4'+N+'°C</b>, sobre los 33,2 del 27/10/2018. <b>Dos detalles que los hacen más interesantes que la cifra.</b> <b>Primero, Quibdó repite:</b> es el <b>segundo récord de octubre de esa misma estación en cinco días</b> —rompió el 1.º con 34,3 y hoy lo sube a 34,5—, en la ciudad más lluviosa del país y que hoy sigue en alerta roja de deslizamiento. <b>Segundo, Medellín rompe su récord de calor el mismo día en que entra en alerta roja de ladera</b>, y lo rompe en <b>La Aldea</b>, que es exactamente la estación que este tablero discutió el 25-sep cuando el usuario preguntó por qué el mapa no mostraba la lluvia de Medellín. <b>Es el noveno récord de octubre de esta serie y el séptimo de clima frío, húmedo o de altiplano:</b> el patrón que el monitor viene señalando desde hace dos semanas se sostiene — el calor extremo no está apareciendo donde se lo espera. <b>El IDEAM no atribuye ninguno a El Niño:</b> el ITD 278 <b>no menciona el fenómeno, ni ENOS, ni sequía, ni déficit de lluvias</b> en ninguna de sus 84 láminas, verificado buscando los siete literales en el PDF descargado — las únicas coincidencias de «enos» son «La Arenosa» y «contactenos@gestiondelriesgo». Tampoco hubo récords de lluvia ni mínimas por debajo de los mínimos históricos, aunque Aldana bajó a 3,8'+N+'°C, Pasto a 4,6 y Toca a 4,8.')

B.append('<b>Nuevo hoy (6-oct) — tres regiones completas no reportan una sola gota: Caribe, Orinoquía e Insular, 136 estaciones en cero.</b> La cobertura nacional de lluvia queda casi igual que ayer —<b>169 de 656 estaciones, el 25,8%</b> frente al 25,1%— y el ITD 278 incluso cuantifica un <b>aumento del 18,3%</b> en los volúmenes nacionales. <b>Pero el promedio nacional esconde el dato:</b> las <b>92 estaciones del Caribe, las 41 de la Orinoquía y las 3 del archipiélago marcan todas cero</b>, y toda la lluvia del país se concentra en la Andina (114 de 375, 30,4%), el Pacífico (48 de 114, <b>42,1%</b>, la región más húmeda hoy) y la Amazonía (7 de 31). El máximo nacional es <b>Pez Fresco, en Santa Rosa de Cabal (Risaralda), con 90,0'+N+'mm</b>, el valor más alto desde los 148,6 de Carepa. <b>La Insular rompe así cinco días consecutivos con el 100% de su red</b> y la Orinoquía completa su tercer día de desplome (79% → 21% → 0%). <b>Y la salvedad no es un adorno, hoy es la clave de lectura:</b> en este servicio un <b>0'+N+'mm no se distingue de «la estación no reportó»</b>, y 525 de los 656 pluviómetros son de lectura manual diaria. Lo que este tablero puede afirmar es que <b>ninguna estación del IDEAM en esas tres regiones reportó lluvia</b>, no que no cayera un milímetro en todo el Caribe. Con tres pluviómetros para dos islas, además, el salto del 100% al 0% en el archipiélago no es una señal climática: es aritmética de muestra pequeña.')

B.append('<b>Nuevo hoy (6-oct) — la cadena de Urabá se cierra donde empezó, y la alerta de ladera se muda al Valle de Aburrá: Antioquia pasa de 14 a 43 municipios en rojo y desplaza al Chocó por primera vez en la serie.</b> Durante tres días este tablero siguió una secuencia en Urabá: <b>Carepa</b> con 148,6'+N+'mm el 2-oct, los municipios del eje bananero en alerta roja de deslizamiento y tres ríos del golfo en alerta hidrológica roja. <b>Hoy se cierra:</b> Carepa hizo 148,6 → 25,9 → <b>0'+N+'mm</b> y <b>sale de la alerta roja</b>, junto con Chigorodó y Nechí. <b>Pero el departamento no se desinfla, se desplaza:</b> entran <b>32 municipios nuevos</b>, casi todos del Valle de Aburrá y del norte y occidente —<b>Medellín</b>, Bello, Urrao, Yarumal, Santa Rosa de Osos, Belmira, Entrerríos, San Pedro de los Milagros, Sopetrán, Liborina, Ebéjico, Heliconia, Santa Fe de Antioquia y veinte más—, y Antioquia queda con <b>43 de las 78 alertas rojas del país</b>, más de la mitad, <b>por delante del Chocó (13) por primera vez en toda esta serie</b>. <b>Dos entradas que vale la pena nombrar:</b> <b>Santa Rosa de Cabal</b> (Risaralda), que es justamente el municipio con el máximo nacional de lluvia del día — la cadena lluvia → ladera cerrándose en un solo municipio y en 24 horas—, y <b>Armenia</b> (Quindío), una capital que no figuraba en esta capa. <b>Y el vacío de fondo cambia de dirección pero no se cierra:</b> cuatro días después, sigue sin haber un solo reporte operativo del <b>DAPARD de Antioquia</b>; lo que antes había que preguntarle por Apartadó y Carepa ahora hay que preguntárselo por Medellín y el norte del departamento.')

B.append('<b>Nuevo hoy (6-oct) — las ocho rojas hidrológicas que ayer «no se movían» se levantaron de golpe: de 12 a 4.</b> Ayer esta caja dedicó una viñeta a que las tres capas de alerta habían cedido al mismo tiempo «menos una»: los ríos, con doce rojas clavadas sin un solo cambio. <b>Hoy ceden ocho</b>, la mayor caída de esta capa en toda la serie, con el total de subzonas en alerta quieto en <b>197</b>. <b>El bloque que se levanta es el del Pacífico sur</b>, que llevaba cuatro días idéntico: salen <b>Río Tola, Río Telembí, Río Patía Medio y Río Patía Bajo</b> (Nariño) y <b>Río Timbiquí y Río San Juan del Micay</b> (Cauca) — de las siete de esa vertiente solo queda <b>Río Saija</b>. Salen también <b>Río Sucio</b> (Antioquia) y la <b>Ciénaga Grande de Santa Marta</b>, que entró ayer como «la primera roja del Magdalena de esta serie» y <b>duró exactamente un día</b>. <b>Las cuatro que quedan:</b> Río León y Río Mulatos (Antioquia), Bajo San Jorge'+N+'–'+N+'La Mojana (Bolívar) y Río Saija (Cauca). <b>Y la lección es la misma que el tablero se escribió el 4-oct con Quibdó, y que vuelve a aplicarse:</b> una entrada en rojo que dura 24 horas no es una señal, y escribir «la primera roja del Magdalena de la serie» sobre una foto de un día le dio más peso del que aguantaba. En siete días esta cifra hizo 1 → 11 → 12 → 12 → <b>4</b>.')

B.append('<b>Nuevo hoy (6-oct) — la alerta de incendio repite el cero y a la vez duplica su huella: de 8 a 18 municipios. No es una contradicción, son dos umbrales.</b> La <b>alerta roja sigue en 0</b> municipios por segundo día —el BAICV N.º 278 vuelve a escribir «<i>Alerta Alta: Sin municipios en alerta</i>»— mientras el total con <i>alguna</i> alerta pasa de <b>8 a 18</b>, revirtiendo cuatro días de caídas (55 → 26 → 12 → 8 → <b>18</b>). Las naranjas suben de 2 a 8 (<b>Neiva, Íquira y Rivera</b> en Huila, <b>Cáqueza</b> en Cundinamarca, <b>Uribia y Manaure</b> en La Guajira, <b>Pasto</b> y <b>Dolores</b>) y las amarillas de 6 a 10, con <b>Cartagena de Indias</b> y <b>Girón</b> entrando y <b>Sabana de Torres bajando de naranja</b>. <b>Qué significa y qué no:</b> el cero dice que el pronóstico a 24 horas no ve condiciones críticas en ningún municipio; el 18 dice que hay el doble de municipios con condiciones de vigilancia que ayer. <b>El titular fácil de hoy —«se duplican las alertas de incendio»— es tan incompleto como el de ayer, «se acabó el riesgo de incendios».</b> Y encaja con el resto del día: las naranjas nuevas están en Huila, Cundinamarca, Nariño y la Alta Guajira, es decir donde hoy no llovió.')

B.append('<b>Nuevo hoy (6-oct) — por primera vez en toda esta serie un cruce de alerta NO cuadra, y conviene decirlo con la misma claridad con que se celebraron los que sí.</b> De los tres niveles del <b>BAICV N.º 278</b>, dos coinciden exactos con el conteo que este monitor hizo por separado del servicio REST: la <b>Alerta Alta sin municipios</b> (mis 0 rojas) y la <b>Alerta Baja en Bolívar, Casanare, Guainía, Norte de Santander, Santander, Tolima y Vichada</b> — los siete departamentos de mis 10 amarillas, uno por uno. <b>Pero la Moderada nombra seis departamentos</b> —La Guajira, Huila, Nariño, Tolima, Cundinamarca y <b>Santander</b>— <b>y mis naranjas están en cinco:</b> en el servicio REST los dos municipios de Santander (Sabana de Torres y Girón) figuran en <b>amarilla</b>, no en naranja. <b>No se puede resolver cuál de los dos tiene razón</b>, y este tablero no va a elegir: las tablas municipales del BAICV <b>pierden la agrupación por nivel al extraer el texto del PDF</b>, un límite que el monitor ya tenía anotado desde el 1-oct, así que el boletín dice «Santander en moderada» en su resumen y su propio anexo no permite verificar a qué columna pertenece Sabana de Torres. <b>Queda como discrepancia abierta.</b> En deslizamientos, en cambio, el cruce vuelve a ser exacto por octavo día: el Pronóstico N.º 278 da amenaza alta en <b>13</b> departamentos y moderada en <b>17</b>, idéntico nombre por nombre.')

B.append('<b>Nuevo hoy (6-oct) — el desfase de dos días queda probado por octava vez, y con veinticuatro valores de estación: el mejor resultado de verificación de toda la serie.</b> Se descargó el <b>Informe Técnico Diario N.º 278</b> (PDF de 84 láminas, publicado el 5-oct a las 12:00 HLC con los datos del <b>4 de octubre</b>, id <code>23367</code>) y sus listados coinciden con el servicio REST en <b>24 valores</b>. En lluvia, los <b>diecisiete</b> municipios que el informe lista por encima de 20'+N+'mm: <b>Santa Rosa de Cabal 90,0</b> como máximo nacional, Quípama 52,5, Sevilla 43,6, Salamina 36,0, Barbacoas 35,0, Palmira 34,4, Ataco 31,0, Cunday 31,0, Bugalagrande 30,0, Cajibío 26,7, Ibagué 26,0, Cartago 26,0, La Pintada 25,9, Líbano 25,0, Taminango 24,0, Policarpa 23,0 y Venecia 23,5. En temperatura, los <b>siete</b> por encima de 35'+N+'°C: <b>Manaure 37,2</b>, Fredonia 37,0, Villavieja 36,8, Natagaima 36,6, Neiva 36,0, Inírida 35,6 y Saldaña 35,2. <b>Las capas de alerta van al día; las de estación, dos días atrás</b>, y la única forma de fechar el dato del servicio REST sigue siendo cruzarlo contra el ITD. <b>Y el refresco fue el mejor de la serie por dos motivos a la vez:</b> solo <b>4 de las 90 lecturas</b> no se actualizaron —iguala el récord del 2 y el 4 de octubre: tres de temperatura (Ortega desde el 23-sep, El Callao en Valledupar desde el 1-oct y una nueva, <b>Carmen de Tonchalá</b> en Cúcuta) y una de lluvia (<b>El Común</b> en Pupiales)— y <b>volvieron a reportar seis, un máximo de la serie</b>: Manaure, Jabalcón (Saldaña), Los Álamos (San Sebastián de Buenavista) y Surbata Bonza (Duitama) en temperatura, y Colegio Agropecuario (Pailitas) y Larandia (Florencia) en lluvia. <b>Es la contracara exacta de la lección de ayer:</b> esta caja escribió que «una estación que vuelve no es una estación que se quedó» a propósito de Manaure, que había reaparecido y vuelto a desaparecer. <b>Hoy Manaure volvió otra vez — y se llevó el máximo nacional con 37,2'+N+'°C.</b>')

B.append('<b>Nuevo hoy (6-oct) — el embalse marca su mayor caída diaria de la serie, 1,06 puntos, y cuatro quintas partes son un cambio de denominador.</b> El volumen útil del SIN cerró el <b>5 de octubre en 75,16%</b>, frente al 76,22% del 4-oct. Es, en el titular, la peor jornada de toda la serie diaria que sigue este monitor. <b>Pero XM volvió a revisar al alza la capacidad útil</b>, de 17.465.538.144 a <b>17.652.543.144 kWh</b> (+187'+N+'GWh): con la capacidad de ayer, el mismo volumen daría <b>75,96%</b>, es decir <b>−0,26 puntos</b>. <b>Dicho sin rodeos: alrededor de 0,80 de los 1,06 puntos son denominador, no agua.</b> Es la <b>tercera revisión de capacidad en cuatro días</b> (3, 4 y 6 de octubre) y la razón por la que este tablero publica la capacidad de cada día junto al porcentaje. <b>Lo que sí bajó de verdad es el volumen:</b> 44,3'+N+'GWh menos en una jornada, el mayor descenso desde el 30 de septiembre. <b>Y los aportes hídricos llevan dos días por debajo del 45%</b> —43,9% el 4-oct, <b>44,5%</b> el 5—, algo que no había ocurrido: el 43,9% sigue siendo el mínimo de la serie. El embalse queda <b>4,84 puntos por debajo del 80%</b> que XM fija como referencia antes de la temporada seca.')

B.append('<b>Nuevo hoy (6-oct) — fuente oficial nueva en la ventana: el Boletín semanal de datos extremos N.º 40 del IDEAM, y pone en perspectiva la semana entera.</b> Publicado el <b>5 de octubre</b> y referido a la semana del <b>28 de septiembre al 4 de octubre</b>, consolida lo que este monitor venía armando día a día: máxima semanal <b>41,0'+N+'°C en Natagaima (estación Anchique)</b> el 29 de septiembre; mínima <b>−0,6'+N+'°C en Cerinza</b> (Boyacá) el mismo día; <b>día más lluvioso del país el miércoles 30 de septiembre</b>, con 8.570,4'+N+'mm sumados en toda la red; y máximo acumulado en 24 horas de <b>148,6'+N+'mm en Carepa</b> (Aeropuerto Los Cedros) el viernes 2 de octubre — el valor que este tablero publicó en su momento, ahora confirmado en el consolidado semanal. <b>Y trae dos cosas que el seguimiento diario no da.</b> <b>La anomalía de septiembre cerrada:</b> déficits <b>superiores al 80%</b> en el oriente de la región Caribe y sectores del nororiente y sur de la Andina y el suroriente del Pacífico, frente a excesos <b>superiores al 90%</b> en el litoral nariñense, el piedemonte amazónico y el norte del Tolima. <b>Y la predicción de anomalía de temperatura para octubre:</b> máximas que podrían superar lo normal <b>entre 4,0 y 5,0'+N+'°C en el norte de Nariño y el sur del Amazonas</b>, y mínimas entre 2,5 y 4,0'+N+'°C por encima de lo normal en el occidente de Antioquia, el occidente de Boyacá, el noroccidente de Cundinamarca, Caldas, el norte del Tolima, el sur del Cauca y el norte de Nariño. <b>El boletín no menciona El Niño</b> y describe septiembre como el mes que «da inicio a la transición hacia la segunda temporada de lluvias del país», la misma fórmula del Boletín 39.')

ins = ''.join('      <li>%s</li>\n' % b for b in B)
anchor = '  <div class="correction-box">\n    <h3>⚠ Antes de leer: correcciones y nota de método</h3>\n    <ul>\n'
assert h.count(anchor) == 1
h = h.replace(anchor, anchor + ins)

open('board_v1.html','w',encoding='utf-8').write(h)
print('correction box done; len', len(h))
